246	% ═══════════════════════════════════════════
247	%  RIGHT COLUMN — Learning Crisis + Quality + Takeaway
248	% ═══════════════════════════════════════════
249	
250	% ── Learning Crisis ──
251	\posterbox[coralcard, title={The Learning Crisis: Enrollment $\neq$ Learning}
252	]{name=learningcrisis, column=2, between=row5 and row9}{
253	  \centering
254	  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
255	    \centering\vspace{6pt}%
256	    {\fontsize{52}{62}\selectfont\bfseries\color{secondary} $<$ 20\%}\\[4pt]
257	    {\fontsize{18}{24}\selectfont\color{textdark} of children in low-income countries achieve minimum reading proficiency by end of primary school}\vspace{6pt}%
258	  }}
259	  \vspace{8pt}
260	  \fontsize{20}{26}\selectfont\color{textdark}
261	  \begin{itemize}[itemsep=6pt]
262	    \item Enrollment numbers mask a \textbf{hidden crisis}
263	    \item Many children cannot identify key ideas in a text or connect them to experiences
264	    \item Being in school $\neq$ learning
265	  \end{itemize}
266	}
267	
268	% ── Quality Inequality — The bold comparison ──
269	\posterbox[coralcard, title={Learning-Adjusted Years of Schooling: A World Divided}
270	]{name=qualitygap, column=2, between=row9 and row15}{
271	  \centering
272	  \vspace{4pt}
273	  % Side-by-side bar comparison
274	  \begin{tikzpicture}[scale=0.75]
275	    % Background grid lines
276	    \foreach \y in {0,2,4,6,8,10} {
277	      \draw[primary!20, thin] (-0.5,\y) -- (10,\y);
278	      \node[left, font=\fontsize{12}{16}\selectfont, textlight] at (-0.5,\y) {\y};
279	    }
280	    % Poorest countries bar
281	    \fill[secondary!85] (1,0) rectangle (4,2.8);
282	    \node[font=\fontsize{18}{22}\selectfont\bfseries, white] at (2.5,1.4) {$<$3 years};
283	    \node[below, font=\fontsize{13}{18}\selectfont, textdark] at (2.5,-0.5) {Poorest countries};
284	    \node[below, font=\fontsize{11}{16}\selectfont, textmid] at (2.5,-1.3) {(Sub-Saharan Africa)};
285	    % Richest countries bar
286	    \fill[accent!90] (6,0) rectangle (9,10.5);
287	    \node[font=\fontsize{18}{22}\selectfont\bfseries, white] at (7.5,5) {10+};
288	    \node[font=\fontsize{18}{22}\selectfont\bfseries, white] at (7.5,3.8) {years};
289	    \node[below, font=\fontsize{13}{18}\selectfont, textdark] at (7.5,-0.5) {Richest countries};
290	    \node[below, font=\fontsize{11}{16}\selectfont, textmid] at (7.5,-1.3) {(High-income nations)};
291	    % Divider
292	    \draw[white, dashed, thick] (5,-1.5) -- (5,11);
293	    % Ratio label
294	    \draw[white, thick, decorate, decoration={brace, amplitude=6pt}]
295	      (9.3,0) -- (9.3,10.5) node[midway, right=10pt, font=\fontsize{12}{16}\selectfont\bfseries, accent] {$>$3.5$\times$};
296	    % Bottom label
297	    \node[font=\fontsize{11}{16}\selectfont, textmid] at (5,-2.2) {Learning-Adjusted Years of Schooling (2020)};
298	  \end{tikzpicture}
299	  \vspace{4pt}
300	  \colorbox{secondary!18}{\parbox{0.92\linewidth}{%
301	    \fontsize{16}{22}\selectfont\color{textdark}
302	    Children in the poorest nations receive \textbf{less than a third} of the quality schooling available to their peers in wealthy countries.%
303	  }}
304	  \vspace{4pt}
305	  \fontsize{16}{22}\selectfont\color{textmid}
306	  South Asia \& Sub-Saharan Africa average: \textbf{$<$7 years}\\
307	  Most of the world's children live in these regions.
308	}
309	
310	% ── Key Takeaway ──
311	\posterbox[darkcard, title={The Job Is Far From Done}
312	]{name=takeaway, column=2, between=row15 and row20}{
313	  \fontsize{22}{28}\selectfont\color{white}
314	  The world has achieved \textbf{\color{accent}remarkable progress} — but the job is far from done.\\[10pt]
315	  \colorbox{accent!25!primary}{\parbox{0.94\linewidth}{%
316	    \fontsize{18}{24}\selectfont\color{white}
317	    \textbf{Hundreds of millions} of children are either out of school or learning very little while in it.%
318	  }}
319	  \vspace{10pt}
320	  \fontsize{20}{26}\selectfont\color{accent}
321	  \textbf{Two gaps demand urgent action:}\\[6pt]
322	  \fontsize{18}{24}\selectfont\color{white}
323	  \begin{enumerate}[itemsep=8pt, leftmargin=18pt]
324	    \item \textbf{Enrollment $\to$ Learning} — attendance without quality is not enough
325	    \item \textbf{Rich $\to$ Poor nations} — equity in quality schooling is the defining challenge of our time
326	  \end{enumerate}
327	  \vspace{8pt}
328	  \centering
329	  \colorbox{accent}{\parbox{0.88\linewidth}{%
330	    \centering\vspace{4pt}%
331	    \fontsize{18}{24}\selectfont\color{primary}\bfseries
332	    Closing these gaps is one of the most\\pressing challenges of our time.%
333	    \vspace{4pt}%
334	  }}
335	}
336	
337	\end{tcbposter}
338	\end{document}
