  \centering
  \renewcommand{\arraystretch}{1.5}
  \fontsize{18}{24}\selectfont
  \begin{tabular}{>{\bfseries}l l}
    \rowcolor{accent!15} Primary & Nearly closed globally \\
    \rowcolor{cardlight} Secondary & Nearly closed globally \\
    \rowcolor{accent!15} Tertiary & \textbf{Women now exceed men} \\
