% ── Learning Crisis ──
\posterbox[coralcard, title={The Learning Crisis: Enrollment $\neq$ Learning}
]{name=learningcrisis, column=2, between=row5 and row9}{
  \centering
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{52}{62}\selectfont\bfseries\color{secondary} $<$ 20\%}\\[4pt]
    {\fontsize{18}{24}\selectfont\color{textdark} of children in low-income countries achieve minimum reading proficiency by end of primary school}\vspace{6pt}%
  }}
  \vspace{8pt}
  \fontsize{20}{26}\selectfont\color{textdark}
  \begin{itemize}[itemsep=6pt]
    \item Enrollment numbers mask a \textbf{hidden crisis}
    \item Many children cannot identify key ideas in a text or connect them to experiences
    \item Being in school $\neq$ learning
  \end{itemize}
}

% ── Quality Inequality — The bold comparison ──
\posterbox[coralcard, title={Learning-Adjusted Years of Schooling: A World Divided}
]{name=qualitygap, column=2, between=row9 and row15}{
  \centering
  \vspace{4pt}
  % Side-by-side bar comparison
  \begin{tikzpicture}[scale=0.78]
    % Background grid lines
    \foreach \y in {0,2,4,6,8,10} {
      \draw[textmid!40, thin] (0,\y) -- (10,\y);
      \node[left, font=\fontsize{11}{14}\selectfont, textmid] at (-0.2,\y) {\y};
    }
    % Poorest countries bar
    \fill[secondary!85] (0.5,0) rectangle (3.5,2.8);
    \node[font=\fontsize{18}{22}\selectfont\bfseries, white] at (2.0,1.4) {$<$3 yrs};
    \node[below, font=\fontsize{13}{18}\selectfont\bfseries, textdark] at (2.0,-0.5) {Poorest};
    \node[below, font=\fontsize{11}{16}\selectfont, textmid] at (2.0,-1.2) {countries};
    % Richest countries bar
    \fill[accent!90] (5.5,0) rectangle (8.5,10.5);
    \node[font=\fontsize{20}{24}\selectfont\bfseries, white] at (7.0,5.8) {10+};
    \node[font=\fontsize{20}{24}\selectfont\bfseries, white] at (7.0,4.2) {years};
    \node[below, font=\fontsize{13}{18}\selectfont\bfseries, textdark] at (7.0,-0.5) {Richest};
    \node[below, font=\fontsize{11}{16}\selectfont, textmid] at (7.0,-1.2) {countries};
    % Divider
    \draw[textmid!50, dashed, thick] (4.5,-1.5) -- (4.5,11);
    % Ratio label
    \draw[secondary, thick, decorate, decoration={brace, amplitude=6pt}]
      (8.8,0) -- (8.8,10.5) node[midway, right=10pt, font=\fontsize{14}{18}\selectfont\bfseries, secondary] {$>$3.5$\times$};
    % Bottom label
    \node[font=\fontsize{11}{16}\selectfont, textmid] at (4.5,-2.2) {Learning-Adjusted Years of Schooling (2020)};
  \end{tikzpicture}
  \vspace{6pt}
  \colorbox{secondary!18}{\parbox{0.92\linewidth}{%
    \fontsize{16}{22}\selectfont\color{textdark}
    Children in the poorest nations receive \textbf{less than a third} of the quality schooling available to their peers in wealthy countries.%
  }}
  \vspace{4pt}
  \fontsize{16}{22}\selectfont\color{textmid}
  South Asia \& Sub-Saharan Africa average: \textbf{$<$7 years}\\
  Most of the world's children live in these regions.
}

% ── Key Takeaway ──
\posterbox[darkcard, title={The Job Is Far From Done}
]{name=takeaway, column=2, between=row15 and row20}{
  \fontsize{22}{28}\selectfont\color{white}
  The world has achieved \textbf{\color{accent}remarkable progress} — but the job is far from done.\\[10pt]
  \colorbox{accent!25!primary}{\parbox{0.94\linewidth}{%
    \fontsize{18}{24}\selectfont\color{white}
    \textbf{Hundreds of millions} of children are either out of school or learning very little while in it.%
  }}
  \vspace{10pt}
  \fontsize{20}{26}\selectfont\color{accent}
  \textbf{Two gaps demand urgent action:}\\[6pt]
  \fontsize{18}{24}\selectfont\color{white}
  \begin{enumerate}[itemsep=8pt, leftmargin=18pt]
    \item \textbf{Enrollment $\to$ Learning} — attendance without quality is not enough
    \item \textbf{Rich $\to$ Poor nations} — equity in quality schooling is the defining challenge of our time
  \end{enumerate}
  \vspace{10pt}
  \centering
  \colorbox{accent}{\parbox{0.88\linewidth}{%
    \centering\vspace{4pt}%
    \fontsize{18}{24}\selectfont\color{primary}\bfseries
    Closing these gaps is one of the most\\pressing challenges of our time.%
    \vspace{4pt}%
  }}
}

