\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{calc,arrows.meta,positioning,shapes.geometric,decorations.pathreplacing}
\pagestyle{empty}

% ═══════════════════════════════════════════
%  COLOR THEME — Deep Navy + Amber/Coral
% ═══════════════════════════════════════════
\definecolor{primary}{HTML}{1B2A4A}       % deep navy
\definecolor{secondary}{HTML}{D94432}     % strong coral/red
\definecolor{accent}{HTML}{F59E0B}        % amber
\definecolor{bgposter}{HTML}{1B2A4A}      % poster background = deep navy
\definecolor{cardlight}{HTML}{F0F4F8}     % light card bg (cool grey)
\definecolor{cardwarm}{HTML}{FFF8F0}      % warm card bg (cream)
\definecolor{cardcoral}{HTML}{FFF5F2}     % coral-tinted card bg
\definecolor{cardamber}{HTML}{FFFBF0}     % amber-tinted card bg
\definecolor{titlecardbg}{HTML}{243B5E}   % slightly lighter navy for dark cards
\definecolor{impactbg}{HTML}{8B1A1A}      % dark red for 244M impact section
\definecolor{textdark}{HTML}{1F2937}      % dark text on light cards
\definecolor{textmid}{HTML}{4B5563}       % medium gray text
\definecolor{textlight}{HTML}{CBD5E1}     % light text on dark bg
\definecolor{statbg}{HTML}{162240}        % slightly darker navy for stat boxes

\pagecolor{bgposter}
\color{white}

% ═══════════════════════════════════════════
%  LIST STYLING
% ═══════════════════════════════════════════
\setlist[itemize]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{accent}\bfseries\arabic*.}}

% ═══════════════════════════════════════════
%  CARD STYLES
% ═══════════════════════════════════════════
\tcbset{
  lightcard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardlight,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=accent!15!white,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top, drop shadow,
  },
  warmcard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardwarm,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=accent!15!white,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top, drop shadow,
  },
  coralcard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardcoral,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=secondary!15!white,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top, drop shadow,
  },
  darkcard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=titlecardbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=primary!70!black,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top, drop shadow,
  },
  impactcard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=impactbg,
    borderline west={6pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=secondary!80!black,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top, drop shadow,
  },
  ambercard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardamber,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{accent!80!black},
    coltitle=accent!80!black, colbacktitle=accent!15!white,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top, drop shadow,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════
%  TITLE BAR
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!85!black, colframe=primary!85!black, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=10pt,
  halign=center, valign=center,
  borderline south={4pt}{0pt}{accent},
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{56}{66}\selectfont\bfseries\color{white} The State of Global Education}\\[10pt]
  {\fontsize{28}{34}\selectfont\color{accent} Progress, Gaps, and Inequality}\\[8pt]
  {\fontsize{18}{24}\selectfont\color{textlight} A data-driven look at how education access, quality, and equity have evolved worldwide}
}

% ═══════════════════════════════════════════
%  PROGRESS BANNER — The triumph
% ═══════════════════════════════════════════
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=16pt, right=16pt, top=10pt, bottom=10pt,
  valign=center,
  borderline south={3pt}{0pt}{accent!40},
]{name=progressbanner, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.3\linewidth}\centering
    \colorbox{primary!50!black}{\parbox{0.88\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{50}{60}\selectfont\bfseries\color{secondary} $<$ 1 in 5}\\[4pt]
      {\fontsize{18}{22}\selectfont\color{textlight} Adults educated, 1800}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.25\linewidth}\centering
    {\fontsize{52}{62}\selectfont\color{accent}$\Longrightarrow$}\\[4pt]
    {\fontsize{16}{20}\selectfont\color{accent}Two centuries\\of expansion}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.3\linewidth}\centering
    \colorbox{accent!20!primary}{\parbox{0.88\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{50}{60}\selectfont\bfseries\color{accent} $>$ 4 in 5}\\[4pt]
      {\fontsize{18}{22}\selectfont\color{white} Adults educated, Today}\vspace{10pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════
%  LEFT COLUMN — Historical Progress + 244M + Gender
% ═══════════════════════════════════════════

% ── Two Centuries of Educational Expansion ──
\posterbox[ambercard, title={Two Centuries of Educational Expansion}
]{name=expansion, column=1, between=row5 and row9}{
  \fontsize{22}{28}\selectfont\color{textdark}
  \begin{itemize}[itemsep=8pt]
    \item In the early 1800s, formal education was a luxury reserved for a small elite
    \item Literacy was rare; the vast majority could not read or write
    \item Over two centuries, this ratio has \textbf{reversed dramatically}
  \end{itemize}
  \vspace{4pt}
  \centering
  \begin{tikzpicture}[scale=0.72]
    \draw[thick, accent, line width=2pt] (0,0) -- (12,0);
    \foreach \x/\yr/\lab in {0/1800/{\scriptsize $<$1 in 5}, 4/1900/{\scriptsize $\sim$2 in 5}, 8/1960/{\scriptsize $\sim$3 in 5}, 12/Today/{\scriptsize $>$4 in 5}} {
      \fill[accent] (\x,0) circle (5pt);
      \node[above=8pt, font=\fontsize{14}{18}\selectfont\bfseries, textdark] at (\x,0) {\yr};
      \node[below=8pt, font=\fontsize{12}{16}\selectfont, secondary] at (\x,0) {\lab};
    }
    \draw[-{Stealth[length=8pt]}, accent, line width=3pt] (0.5,-1.2) -- (11.5,-1.2);
    \node[font=\fontsize{12}{16}\selectfont\bfseries, accent] at (6,-1.8) {Universal access within reach};
  \end{tikzpicture}
}

% ── 244 MILLION — The dominant visual (DARK background, white text) ──
\posterbox[impactcard, title={244 Million Children Still Out of School}
]{name=outofschool, column=1, between=row9 and row15}{
  \centering
  {\fontsize{68}{80}\selectfont\bfseries\color{white} 244 MILLION}\\[6pt]
  {\fontsize{20}{26}\selectfont\color{accent} children of school age not enrolled (2023)}\\[14pt]
  % Breakdown bars
  \begin{tikzpicture}[scale=0.78]
    % Primary bar
    \fill[accent!80] (0,1.8) rectangle (2.2,3.0);
    \node[right, font=\fontsize{16}{20}\selectfont\bfseries, white] at (0.2,2.4) {Primary};
    \node[right, font=\fontsize{16}{20}\selectfont, textlight] at (3.8,2.4) {$\sim$60 million};
    % Secondary bar (much longer — dominant)
    \fill[secondary] (0,0) rectangle (7.0,1.2);
    \node[right, font=\fontsize{16}{20}\selectfont\bfseries, white] at (0.2,0.6) {Secondary};
    \node[right, font=\fontsize{16}{20}\selectfont, textlight] at (8.0,0.6) {$\sim$184 million};
    % Brace for total
    \draw[accent, thick, decorate, decoration={brace, amplitude=8pt, mirror}]
      (7.4,0) -- (7.4,3.0) node[midway, right=12pt, font=\fontsize{16}{20}\selectfont\bfseries, accent] {244M total};
  \end{tikzpicture}
  \vspace{6pt}
  \colorbox{impactbg!60!black}{\parbox{0.92\linewidth}{%
    \fontsize{18}{24}\selectfont\color{white}
    \textbf{Secondary dropout is the major driver} — many children complete primary but do not continue.%
  }}
}

% ── Gender Gap ──
\posterbox[lightcard, title={Closing the Gender Gap}
]{name=gendergap, column=1, between=row15 and row18}{
  \fontsize{20}{26}\selectfont\color{textdark}
  The global gender gap in enrollment has \textbf{largely closed}:\\[6pt]
  \centering
  \renewcommand{\arraystretch}{1.5}
  \fontsize{18}{24}\selectfont
  \begin{tabular}{>{\bfseries}l l}
    \rowcolor{accent!15} Primary & Nearly closed globally \\
    \rowcolor{cardlight} Secondary & Nearly closed globally \\
    \rowcolor{accent!15} Tertiary & \textbf{Women now exceed men} \\
  \end{tabular}
  \vspace{6pt}
  \flushleft
  \fontsize{16}{22}\selectfont\color{secondary}
  \textbf{Exception:} In Afghanistan, girls remain far less likely to attend school at any level.
}

% ── Sources ──
\posterbox[darkcard, title={Sources}
]{name=sources, column=1, between=row18 and row20}{
  \fontsize{16}{22}\selectfont\color{textlight}
  \begin{itemize}[itemsep=4pt, leftmargin=14pt]
    \item UNESCO Institute for Statistics (2023)
    \item World Bank Development Indicators
    \item Our World in Data --- Education
  \end{itemize}
}

% ═══════════════════════════════════════════
%  RIGHT COLUMN — Learning Crisis + Quality + Takeaway
% ═══════════════════════════════════════════

% ── Learning Crisis ──
\posterbox[coralcard, title={The Learning Crisis: Enrollment $\neq$ Learning}
]{name=learningcrisis, column=2, between=row5 and row9}{
  \centering
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{52}{62}\selectfont\bfseries\color{secondary} $<$ 20\%}\\[4pt]
    {\fontsize{18}{24}\selectfont\color{textdark} of children in low-income countries achieve minimum reading proficiency by end of primary school}\vspace{6pt}%
  }}
  \vspace{8pt}
  \fontsize{20}{26}\selectfont\color{textdark}
  \begin{itemize}[itemsep=6pt]
    \item Enrollment numbers mask a \textbf{hidden crisis}
    \item Many children cannot identify key ideas in a text or connect them to experiences
    \item Being in school $\neq$ learning
  \end{itemize}
}

% ── Quality Inequality — The bold comparison ──
\posterbox[coralcard, title={Learning-Adjusted Years of Schooling: A World Divided}
]{name=qualitygap, column=2, between=row9 and row15}{
  \centering
  \vspace{4pt}
  % Side-by-side bar comparison
  \begin{tikzpicture}[scale=0.78]
    % Background grid lines
    \foreach \y in {0,2,4,6,8,10} {
      \draw[textmid!40, thin] (0,\y) -- (10,\y);
      \node[left, font=\fontsize{11}{14}\selectfont, textmid] at (-0.2,\y) {\y};
    }
    % Poorest countries bar
    \fill[secondary!85] (0.5,0) rectangle (3.5,2.8);
    \node[font=\fontsize{18}{22}\selectfont\bfseries, white] at (2.0,1.4) {$<$3 yrs};
    \node[below, font=\fontsize{13}{18}\selectfont\bfseries, textdark] at (2.0,-0.5) {Poorest};
    \node[below, font=\fontsize{11}{16}\selectfont, textmid] at (2.0,-1.2) {countries};
    % Richest countries bar
    \fill[accent!90] (5.5,0) rectangle (8.5,10.5);
    \node[font=\fontsize{20}{24}\selectfont\bfseries, white] at (7.0,5.8) {10+};
    \node[font=\fontsize{20}{24}\selectfont\bfseries, white] at (7.0,4.2) {years};
    \node[below, font=\fontsize{13}{18}\selectfont\bfseries, textdark] at (7.0,-0.5) {Richest};
    \node[below, font=\fontsize{11}{16}\selectfont, textmid] at (7.0,-1.2) {countries};
    % Divider
    \draw[textmid!50, dashed, thick] (4.5,-1.5) -- (4.5,11);
    % Ratio label
    \draw[secondary, thick, decorate, decoration={brace, amplitude=6pt}]
      (8.8,0) -- (8.8,10.5) node[midway, right=10pt, font=\fontsize{14}{18}\selectfont\bfseries, secondary] {$>$3.5$\times$};
    % Bottom label
    \node[font=\fontsize{11}{16}\selectfont, textmid] at (4.5,-2.2) {Learning-Adjusted Years of Schooling (2020)};
  \end{tikzpicture}
  \vspace{6pt}
  \colorbox{secondary!18}{\parbox{0.92\linewidth}{%
    \fontsize{16}{22}\selectfont\color{textdark}
    Children in the poorest nations receive \textbf{less than a third} of the quality schooling available to their peers in wealthy countries.%
  }}
  \vspace{4pt}
  \fontsize{16}{22}\selectfont\color{textmid}
  South Asia \& Sub-Saharan Africa average: \textbf{$<$7 years}\\
  Most of the world's children live in these regions.
}

% ── Key Takeaway ──
\posterbox[darkcard, title={The Job Is Far From Done}
]{name=takeaway, column=2, between=row15 and row20}{
  \fontsize{22}{28}\selectfont\color{white}
  The world has achieved \textbf{\color{accent}remarkable progress} — but the job is far from done.\\[10pt]
  \colorbox{accent!25!primary}{\parbox{0.94\linewidth}{%
    \fontsize{18}{24}\selectfont\color{white}
    \textbf{Hundreds of millions} of children are either out of school or learning very little while in it.%
  }}
  \vspace{10pt}
