% ── Two Centuries of Educational Expansion ──
\posterbox[ambercard, title={Two Centuries of Educational Expansion}
]{name=expansion, column=1, between=row5 and row9}{
  \fontsize{22}{28}\selectfont\color{textdark}
  \begin{itemize}[itemsep=8pt]
    \item In the early 1800s, formal education was a luxury reserved for a small elite
    \item Literacy was rare; the vast majority could not read or write
    \item Over two centuries, this ratio has \textbf{reversed dramatically}
  \end{itemize}
  \vspace{4pt}
  \centering
  \begin{tikzpicture}[scale=0.72]
    \draw[thick, accent, line width=2pt] (0,0) -- (12,0);
    \foreach \x/\yr/\lab in {0/1800/{\scriptsize $<$1 in 5}, 4/1900/{\scriptsize $\sim$2 in 5}, 8/1960/{\scriptsize $\sim$3 in 5}, 12/Today/{\scriptsize $>$4 in 5}} {
      \fill[accent] (\x,0) circle (5pt);
      \node[above=8pt, font=\fontsize{14}{18}\selectfont\bfseries, textdark] at (\x,0) {\yr};
      \node[below=8pt, font=\fontsize{12}{16}\selectfont, secondary] at (\x,0) {\lab};
    }
    \draw[-{Stealth[length=8pt]}, accent, line width=3pt] (0.5,-1.2) -- (11.5,-1.2);
    \node[font=\fontsize{12}{16}\selectfont\bfseries, accent] at (6,-1.8) {Universal access within reach};
  \end{tikzpicture}
}

% ── 244 MILLION — The dominant visual (DARK background, white text) ──
\posterbox[impactcard, title={244 Million Children Still Out of School}
]{name=outofschool, column=1, between=row9 and row15}{
  \centering
  {\fontsize{68}{80}\selectfont\bfseries\color{white} 244 MILLION}\\[6pt]
  {\fontsize{20}{26}\selectfont\color{accent} children of school age not enrolled (2023)}\\[14pt]
  % Breakdown bars
  \begin{tikzpicture}[scale=0.78]
    % Primary bar
    \fill[accent!80] (0,1.8) rectangle (2.2,3.0);
    \node[right, font=\fontsize{16}{20}\selectfont\bfseries, white] at (0.2,2.4) {Primary};
    \node[right, font=\fontsize{16}{20}\selectfont, textlight] at (3.8,2.4) {$\sim$60 million};
    % Secondary bar (much longer — dominant)
    \fill[secondary] (0,0) rectangle (7.0,1.2);
    \node[right, font=\fontsize{16}{20}\selectfont\bfseries, white] at (0.2,0.6) {Secondary};
    \node[right, font=\fontsize{16}{20}\selectfont, textlight] at (8.0,0.6) {$\sim$184 million};
