265	}
266	
267	% ── Quality Inequality — The bold comparison ──
268	\posterbox[coralcard, title={Learning-Adjusted Years of Schooling: A World Divided}
269	]{name=qualitygap, column=2, between=row9 and row15}{
270	  \centering
271	  \vspace{4pt}
272	  % Side-by-side bar comparison
273	  \begin{tikzpicture}[scale=0.78]
274	    % Background grid lines
275	    \foreach \y in {0,2,4,6,8,10} {
276	      \draw[textmid!40, thin] (0,\y) -- (10,\y);
277	      \node[left, font=\fontsize{11}{14}\selectfont, textmid] at (-0.2,\y) {\y};
278	    }
279	    % Poorest countries bar
280	    \fill[secondary!85] (0.5,0) rectangle (3.5,2.8);
281	    \node[font=\fontsize{18}{22}\selectfont\bfseries, white] at (2.0,1.4) {$<$3 yrs};
282	    \node[below, font=\fontsize{13}{18}\selectfont\bfseries, textdark] at (2.0,-0.5) {Poorest};
283	    \node[below, font=\fontsize{11}{16}\selectfont, textmid] at (2.0,-1.2) {countries};
284	    % Richest countries bar
285	    \fill[accent!90] (5.5,0) rectangle (8.5,10.5);
286	    \node[font=\fontsize{20}{24}\selectfont\bfseries, white] at (7.0,5.8) {10+};
287	    \node[font=\fontsize{20}{24}\selectfont\bfseries, white] at (7.0,4.2) {years};
288	    \node[below, font=\fontsize{13}{18}\selectfont\bfseries, textdark] at (7.0,-0.5) {Richest};
289	    \node[below, font=\fontsize{11}{16}\selectfont, textmid] at (7.0,-1.2) {countries};
290	    % Divider
291	    \draw[textmid!50, dashed, thick] (4.5,-1.5) -- (4.5,11);
292	    % Ratio label
293	    \draw[secondary, thick, decorate, decoration={brace, amplitude=6pt}]
294	      (8.8,0) -- (8.8,10.5) node[midway, right=10pt, font=\fontsize{14}{18}\selectfont\bfseries, secondary] {$>$3.5$\times$};
295	    % Bottom label
296	    \node[font=\fontsize{11}{16}\selectfont, textmid] at (4.5,-2.2) {Learning-Adjusted Years of Schooling (2020)};
297	  \end{tikzpicture}
298	  \vspace{6pt}
299	  \colorbox{secondary!18}{\parbox{0.92\linewidth}{%
300	    \fontsize{16}{22}\selectfont\color{textdark}
301	    Children in the poorest nations receive \textbf{less than a third} of the quality schooling available to their peers in wealthy countries.%
302	  }}
303	  \vspace{4pt}
304	  \fontsize{16}{22}\selectfont\color{textmid}
305	  South Asia \& Sub-Saharan Africa average: \textbf{$<$7 years}\\
306	  Most of the world's children live in these regions.
307	}
308	
309	% ── Key Takeaway ──
310	\posterbox[darkcard, title={The Job Is Far From Done}
311	]{name=takeaway, column=2, between=row15 and row20}{
312	  \fontsize{22}{28}\selectfont\color{white}
313	  The world has achieved \textbf{\color{accent}remarkable progress} — but the job is far from done.\\[10pt]
314	  \colorbox{accent!25!primary}{\parbox{0.94\linewidth}{%
315	    \fontsize{18}{24}\selectfont\color{white}
316	    \textbf{Hundreds of millions} of children are either out of school or learning very little while in it.%
317	  }}
318	  \vspace{10pt}
319	  \fontsize{20}{26}\selectfont\color{accent}
320	  \textbf{Two gaps demand urgent action:}\\[6pt]
321	  \fontsize{18}{24}\selectfont\color{white}
322	  \begin{enumerate}[itemsep=8pt, leftmargin=18pt]
323	    \item \textbf{Enrollment $\to$ Learning} — attendance without quality is not enough
324	    \item \textbf{Rich $\to$ Poor nations} — equity in quality schooling is the defining challenge of our time
325	  \end{enumerate}
326	  \vspace{10pt}
327	  \centering
328	  \colorbox{accent}{\parbox{0.88\linewidth}{%
329	    \centering\vspace{4pt}%
330	    \fontsize{18}{24}\selectfont\color{primary}\bfseries
331	    Closing these gaps is one of the most\\pressing challenges of our time.%
332	    \vspace{4pt}%
333	  }}
334	}
335	
336	\end{tcbposter}
337	\end{document}
